\title{The Moment Spectrum and the Dimension of the \\ Leading-Term Cancellation Space}
\author{Aristotle}
\date{2026-07-10}

\begin{document}

\begin{abstract}
We study the leading correction to a heat-kernel--type spectral trace,
$L(t) = \sum_{i=1}^{n} d_i\, e^{-t E_i}$, where $E = (E_1,\dots,E_n)$ is a real
spectrum and $d = (d_1,\dots,d_n)$ is a vector of diagonal shifts. We prove three
sharp structural characterizations of the condition ``$L(t) = 0$ for all
$t \in \R$.'' First, a \emph{moment-spectrum equivalence}: the leading term
cancels for all $t$ if and only if every spectral power sum
$m_k = \sum_i d_i E_i^k$ vanishes, converting a transcendental identity into a
countable family of algebraic ones. Second, a realization of the cancellation
condition as the \emph{kernel of a single linear level-aggregation map} $S$,
which sends a shift vector to the tuple of its aggregate shifts over the distinct
energy levels. Third, an exact \emph{dimension formula}: the cancellation space
has dimension $n - m$, where $m$ is the number of distinct energy levels. As a
corollary, nontrivial cancellation exists if and only if the spectrum is
degenerate. All three facts trace back to the nonsingularity of a Vandermonde
system on the distinct energy values.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Motivation}
Spectral traces of the form $\sum_i w_i\, e^{-t E_i}$ pervade heat-kernel
expansions, partition functions in statistical mechanics, and semiclassical
approximations. In many settings one is interested not in the leading trace
itself but in its \emph{first correction} under an expansion in a large parameter
$N$ --- the term surviving at order $1/N$. Abstractly this correction has the
shape
\[
L(t) = \sum_{i=1}^{n} d_i \, e^{-t E_i},
\]
where the $E_i$ are the (real) energy levels and the $d_i$ encode the first-order
diagonal shifts induced by the perturbation. A recurring phenomenon is that this
correction vanishes identically in $t$: the leading contribution \emph{cancels},
robustly, at every temperature. Empirically this is associated with
\emph{degeneracy} --- energy levels shared by several states.

An earlier development established the level-by-level criterion: $L \equiv 0$ if
and only if the aggregate diagonal shift over each degenerate energy level is
zero. The present paper deepens that result in two independent directions and
unifies them.

\subsection{Summary of results}
Throughout, $n \ge 0$, $E, d : \{1,\dots,n\} \to \R$, and $m = |\{E_i : i\}|$
denotes the number of distinct energy values.
\begin{itemize}
\item \textbf{Theorem A (Moment spectrum).} $L(t) = 0$ for all $t$ iff
  $m_k := \sum_i d_i E_i^k = 0$ for all $k \in \N$.
\item \textbf{Theorem B (Kernel realization).} There is a linear map $S$ whose
  kernel is exactly the set of shift vectors $d$ with $L \equiv 0$.
\item \textbf{Theorem C (Dimension formula).} The cancellation space has
  dimension $n - m$.
\item \textbf{Corollary D (Degeneracy criterion).} A nonzero $d$ with
  $L \equiv 0$ exists iff $m < n$.
\end{itemize}
The technical engine common to all four is the nonsingularity of the Vandermonde
matrix on the distinct energy values.

\section{Definitions and setup}

\begin{definition}[Leading term]
Given $E, d : \{1,\dots,n\} \to \R$, the \emph{leading term} is
\[
L(t) = \sum_{i=1}^{n} d_i\, e^{-t E_i}, \qquad t \in \R.
\]
\end{definition}

\begin{definition}[Distinct levels and level sums]
Let $V = \{E_i : 1 \le i \le n\}$ be the finite set of \emph{distinct energy
values}, and $m = |V|$. For $v \in V$, the \emph{aggregate shift} (\emph{level
sum}) at $v$ is $s_v = \sum_{j : E_j = v} d_j$.
\end{definition}

\begin{proposition}[Level-sum criterion, prior result]\label{prop:levelsum}
$L(t) = 0$ for all $t \in \R$ if and only if $s_v = 0$ for every $v \in V$.
\end{proposition}

The idea: grouping the defining sum by energy value, $L(t) = \sum_{v \in V} s_v\,
e^{-tv}$; the functions $t \mapsto e^{-tv}$ for distinct $v$ are linearly
independent, so $L \equiv 0$ iff each coefficient $s_v$ vanishes. We use
Proposition~\ref{prop:levelsum} as a black box.

\begin{definition}[Spectral moments]
For $k \in \N$, the $k$-th \emph{spectral moment} is $m_k = \sum_{i=1}^{n} d_i\,
E_i^{\,k}$, with the convention $0^0 = 1$.
\end{definition}

\section{The Vandermonde moment lemma}

\begin{lemma}[Coefficients vanish from vanishing moments]\label{lem:vand}
Let $\iota$ be finite and $x, c : \iota \to \R$ with $x$ injective. If
$\sum_{i \in \iota} c_i\, x_i^{\,k} = 0$ for every $k \in \N$, then $c_i = 0$ for
every $i$.
\end{lemma}

\begin{proof}[Proof sketch]
Let $N = |\iota|$ and enumerate $\iota$ as $i_1,\dots,i_N$. The $N \times N$
Vandermonde matrix $\mathrm{Vand}$ with $\mathrm{Vand}_{k,\ell} =
x_{i_\ell}^{\,k}$ ($k,\ell \in \{0,\dots,N-1\}$) has determinant
$\prod_{\ell < \ell'} (x_{i_{\ell'}} - x_{i_\ell}) \neq 0$ by injectivity. The
hypotheses for $k = 0,\dots,N-1$ say $\mathrm{Vand}\, c = 0$; invertibility forces
$c = 0$. Only the first $N$ moments are needed.
\end{proof}

\begin{remark}
Lemma~\ref{lem:vand} is load-bearing: the reverse implication of Theorem~A fails
without Vandermonde nonsingularity.
\end{remark}

\section{Fibrewise decomposition of moments}

\begin{lemma}[Level decomposition of a moment]\label{lem:decomp}
For every $k \in \N$,
\[
\sum_{i=1}^{n} d_i\, E_i^{\,k} = \sum_{v \in V} v^{\,k}\, \Big(\sum_{j : E_j = v} d_j\Big) = \sum_{v \in V} v^{\,k}\, s_v.
\]
\end{lemma}

\begin{proof}[Proof sketch]
Partition $\{1,\dots,n\}$ into the disjoint fibers $\{j : E_j = v\}$ over
$v \in V$. On the fiber over $v$, $E_j = v$, so $d_j E_j^k = v^k d_j$. Summing over
each fiber and then over $v$ regroups the total sum as claimed.
\end{proof}

\section{Theorem A: the moment-spectrum equivalence}

\begin{theorem}[Leading-term cancellation, moment form]\label{thm:A}
For any $E$ and $d$,
\[
\big(\forall t \in \R,\ L(t) = 0\big) \iff \big(\forall k \in \N,\ \textstyle\sum_i d_i E_i^k = 0\big).
\]
\end{theorem}

\begin{proof}[Proof sketch]
($\Rightarrow$) If $L \equiv 0$ then by Proposition~\ref{prop:levelsum} every
$s_v = 0$, so by Lemma~\ref{lem:decomp}, $m_k = \sum_v v^k s_v = 0$ for all $k$.

($\Leftarrow$) Assume all $m_k = 0$. Apply Lemma~\ref{lem:vand} with $\iota = V$,
$x(v) = v$ (injective, as $V$ has distinct elements), and $c(v) = s_v$. By
Lemma~\ref{lem:decomp}, $\sum_{v} c(v) x(v)^k = \sum_v v^k s_v = m_k = 0$ for all
$k$; hence every $s_v = 0$, and Proposition~\ref{prop:levelsum} gives $L \equiv
0$.
\end{proof}

\begin{remark}
Theorem~\ref{thm:A} trades the transcendental family $\{t \mapsto e^{-tE_i}\}$
for the algebraic family $\{E_i^k\}$; both separate distinct levels, the former by
linear independence of exponentials, the latter by the Vandermonde determinant.
\end{remark}

\section{Theorems B and C: the cancellation space and its dimension}

\begin{definition}[Level-aggregation map]
Let $V = \{E_i : i\}$, $m = |V|$. The \emph{level-aggregation map} is the linear
map $S : \R^n \to \R^{V}$, $S(d)(v) = \sum_{j : E_j = v} d_j = s_v$.
\end{definition}

\begin{definition}[Cancellation space]
$\mathcal{C}(E) = \{\, d \in \R^n : L(t) = 0 \text{ for all } t \,\}$.
\end{definition}

\begin{theorem}[Kernel realization]\label{thm:B}
$\mathcal{C}(E) = \ker S$; in particular it is a linear subspace of $\R^n$.
\end{theorem}

\begin{proof}[Proof sketch]
By Proposition~\ref{prop:levelsum}, $d \in \mathcal{C}(E)$ iff $s_v = 0$ for all
$v$, i.e. $S(d) = 0$. A kernel is a subspace.
\end{proof}

\begin{lemma}[Surjectivity]\label{lem:surj}
$S : \R^n \to \R^V$ is surjective.
\end{lemma}

\begin{proof}[Proof sketch]
Each fiber $\{j : E_j = v\}$ is nonempty. Given $b \in \R^V$, pick a
representative $j(v)$ per fiber, set $d_{j(v)} = b(v)$, all else zero; then
$S(d) = b$.
\end{proof}

\begin{theorem}[Dimension formula]\label{thm:C}
$\dim \mathcal{C}(E) = n - m$, where $m = |\{E_i : i\}|$.
\end{theorem}

\begin{proof}[Proof sketch]
Rank--nullity for $S : \R^n \to \R^V$ gives $\dim \ker S + \rank S = n$. By
Lemma~\ref{lem:surj}, $\rank S = |V| = m$. Hence $\dim \ker S = n - m$, and by
Theorem~\ref{thm:B} this equals $\dim \mathcal{C}(E)$.
\end{proof}

\begin{remark}
Since $V$ is the image of an $n$-element set, $m \le n$, so $n - m \ge 0$. The
quantity $n - m$ is the total spectral degeneracy: each merged pair of states
contributes one independent direction of cancellation.
\end{remark}

\begin{corollary}[Nontrivial cancellation iff degenerate]\label{cor:D}
A nonzero $d \in \R^n$ with $L(t) = 0$ for all $t$ exists iff $m < n$.
\end{corollary}

\begin{proof}[Proof sketch]
A nonzero element of $\mathcal{C}(E)$ exists iff $\dim \mathcal{C}(E) > 0$, i.e.
by Theorem~\ref{thm:C} iff $n - m > 0$. Since $m \le n$, this is $m < n$, the
degeneracy condition.
\end{proof}

\section{Worked examples}

\begin{example}[Doubly degenerate pair, $n=2$, $m=1$]
$E = (a,a)$. Condition: $s_a = d_1 + d_2 = 0$, a line; dimension $2 - 1 = 1$. The
vector $d = (c,-c)$ has $m_k = c a^k - c a^k = 0$ for all $k$, and
$L(t) = c e^{-ta} - c e^{-ta} = 0$.
\end{example}

\begin{example}[Non-degenerate pair, $n=2$, $m=2$]
$E = (0,1)$. Conditions $d_1 = 0$, $d_2 = 0$ force $d = 0$; dimension $2 - 2 = 0$.
No nontrivial cancellation, per Corollary~\ref{cor:D}.
\end{example}

\begin{example}[Triple with one coincidence, $n=3$, $m=2$]
$E = (a,a,b)$, $a \neq b$. Solutions $\{(c,-c,0)\}$ have dimension $3 - 2 = 1$.
\end{example}

\section{Algorithms}

\begin{algorithm}[Cancellation-space dimension]
Given $E \in \R^n$, compute $m = |\{E_i\}|$ (deduplicate up to tolerance) and
return $n - m$. Complexity $O(n \log n)$.
\end{algorithm}

\begin{algorithm}[Cancellation-space basis]
Group indices into fibers $F_1,\dots,F_m$. For each fiber with anchor $a$ and each
$j \in F \setminus \{a\}$, emit $e_j - e_a$. These $n - m$ vectors form a basis
of $\mathcal{C}(E)$. Complexity $O(n)$ after grouping.
\end{algorithm}

\begin{algorithm}[Moment-based cancellation test]
By Theorem~\ref{thm:A} and Lemma~\ref{lem:vand}, checking the first $m$ moments
(equivalently, all level sums) suffices. Report cancellation iff every $s_v$ is
numerically zero. Complexity $O(n + m^2)$.
\end{algorithm}

\section{Discussion}

Leading-term cancellation is controlled by one linear level-aggregation map: its
kernel is the cancellation space (dimension $n - m$), its triviality is equivalent
to the vanishing of every spectral power sum, and both trace back to the
Vandermonde invertibility on distinct energy values. Three perspectives meet:
spectral analysis (the transcendental identity), the combinatorics of degeneracy
(the block count $m$), and finite-dimensional linear algebra (rank--nullity). A
notable feature is dimensional universality: $\dim \mathcal{C}(E) = n - m$ depends
only on the number of distinct levels, not their values.

\section{Future directions}

\subsection*{Sub-leading cancellation within a fixed degeneracy pattern}
Fix the partition into equal-energy blocks. When the leading correction cancels,
the next-order correction $\sum_i d_i^2 e^{-tE_i}$ should cancel for all $t$ iff
the second-order shifts balance block-by-block, with a cancellation space of the
same dimension $n - m$: each order sees the spectrum only through the same
level-aggregation map.

\subsection*{Minimal sampling}
For $m$ distinct levels, the leading term should cancel for all $t$ once it
cancels at any $m$ distinct sample points $t_1,\dots,t_m$: the level-projected
function lies in an $m$-dimensional space of exponentials.

\subsection*{Degeneracy detection from dimension alone}
The cancellation dimension should be a complete invariant of coarse degeneracy:
two spectra match across all perturbation classes iff they have the same number
of distinct levels.

\subsection*{Weighted / density-of-states generalization}
Replace level counting by positive weights $w_i$ (a density of states) and study
the corresponding weighted level-aggregation map.

\section{Conclusion}

We have given three equivalent characterizations of leading-term cancellation: a
moment-spectrum criterion, a kernel realization via a single linear
level-aggregation map, and an exact dimension formula $n - m$, with the corollary
that nontrivial cancellation is possible exactly when the spectrum is degenerate.
The unifying mechanism is Vandermonde nonsingularity on distinct energy values.

\end{document}

