"""Demo 1: Moment-spectrum equivalence (Theorem A).

Verifies that the leading term L(t) = sum_i d_i exp(-t E_i) vanishes for all t
exactly when every spectral moment m_k = sum_i d_i E_i^k vanishes, which in turn
holds exactly when every aggregate level sum s_v = sum_{E_j=v} d_j is zero.
"""
from __future__ import annotations
import math
from typing import Dict, List, Sequence


def leading_term(E: Sequence[float], d: Sequence[float], t: float) -> float:
    return sum(di * math.exp(-t * Ei) for Ei, di in zip(E, d))


def spectral_moment(E: Sequence[float], d: Sequence[float], k: int) -> float:
    return sum(di * (Ei ** k) for Ei, di in zip(E, d))


def distinct_levels(E: Sequence[float], tol: float = 1e-9) -> List[float]:
    vals: List[float] = []
    for Ei in sorted(E):
        if not vals or abs(Ei - vals[-1]) > tol:
            vals.append(Ei)
    return vals


def level_sums(E: Sequence[float], d: Sequence[float], tol: float = 1e-9) -> Dict[float, float]:
    levels = distinct_levels(E, tol)
    sums = {v: 0.0 for v in levels}
    for Ei, di in zip(E, d):
        v = min(levels, key=lambda w: abs(w - Ei))
        sums[v] += di
    return sums


if __name__ == "__main__":
    E = [1.0, 1.0, 3.0]
    d = [2.0, -2.0, 0.0]
    m = len(distinct_levels(E))
    print("level sums:", level_sums(E, d))
    print("moments:", [round(spectral_moment(E, d, k), 12) for k in range(2 * m)])
    print("L(t):", [round(leading_term(E, d, t), 12) for t in (-1, 0, 0.5, 2, 5)])

"""Demo 3: Minimal sampling and moment truncation.

Illustrates that for a spectrum with m distinct levels it suffices to test the
first m moments (equivalently m sample temperatures) to certify cancellation for
all t -- the transcendental identity is finite-dimensional in disguise.
"""
from __future__ import annotations
import math
from typing import List, Sequence


def distinct_levels(E: Sequence[float], tol: float = 1e-9) -> List[float]:
    vals: List[float] = []
    for Ei in sorted(E):
        if not vals or abs(Ei - vals[-1]) > tol:
            vals.append(Ei)
    return vals


def spectral_moment(E: Sequence[float], d: Sequence[float], k: int) -> float:
    return sum(di * (Ei ** k) for Ei, di in zip(E, d))


def leading_term(E: Sequence[float], d: Sequence[float], t: float) -> float:
    return sum(di * math.exp(-t * Ei) for Ei, di in zip(E, d))


def certified_by_first_m_moments(E: Sequence[float], d: Sequence[float], tol: float = 1e-9) -> bool:
    m = len(distinct_levels(E, tol))
    return all(abs(spectral_moment(E, d, k)) <= tol for k in range(m))


if __name__ == "__main__":
    E = [0.0, 2.0, 2.0, 5.0]
    d_cancel = [0.0, 3.0, -3.0, 0.0]
    d_no = [1.0, 0.0, 0.0, -1.0]
    for d in (d_cancel, d_no):
        cert = certified_by_first_m_moments(E, d)
        actual = max(abs(leading_term(E, d, t)) for t in (0, 0.5, 1, 2, 4))
        print(f"d={d} certified={cert} max|L(t)|~{actual:.3e}")

