from __future__ import annotations
from typing import List, Sequence


def cancellation_dimension(E: Sequence[float], tol: float = 1e-9) -> int:
    """Return dim of the cancellation space = n - m (Theorem C)."""
    vals: List[float] = []
    for Ei in sorted(E):
        if not vals or abs(Ei - vals[-1]) > tol:
            vals.append(Ei)
    return len(E) - len(vals)

from __future__ import annotations
from typing import Dict, List, Sequence


def moment_cancellation_test(E: Sequence[float], d: Sequence[float], tol: float = 1e-9) -> bool:
    """Certify L(t)==0 for all t by checking every aggregate level sum is zero."""
    levels: List[float] = []
    for Ei in sorted(E):
        if not levels or abs(Ei - levels[-1]) > tol:
            levels.append(Ei)
    sums: Dict[float, float] = {v: 0.0 for v in levels}
    for Ei, di in zip(E, d):
        v = min(levels, key=lambda w: abs(w - Ei))
        sums[v] += di
    return all(abs(s) <= tol for s in sums.values())
